    'val.ms_ip_in_range_res': 'Choisir une IP libre hors des plages Services Runtime / VCF Automation.',
    'val.fqdn_local': 'Domaine DNS en .local : non supporté par VCF 9.1 (FQDN conformes RFC requis).',
